function mergeRanges(ranges: number[][]): number[][] {
  let blocks: number[][] = [];
  for (const [s0, e0] of ranges) {
    let s = s0, e = e0;
    const keep: number[][] = [];
    for (const b of blocks) {
      if (b[0] <= e && s <= b[1]) { s = Math.min(s, b[0]); e = Math.max(e, b[1]); }
      else keep.push(b);
    }
    keep.push([s, e]);
    blocks = keep;
  }
  return blocks.sort((a, b) => a[0] - b[0]);
}

