    def mergeRanges(self, ranges: List[List[int]]) -> List[List[int]]:
        blocks = []
        for s, e in ranges:
            keep = []
            for b in blocks:
                if b[0] <= e and s <= b[1]:
                    s, e = min(s, b[0]), max(e, b[1])
                else:
                    keep.append(b)
            keep.append([s, e])
            blocks = keep
        return sorted(blocks)

