function mergeRanges(ranges: number[][]): number[][] {
  const sorted = ranges.map(r => [r[0], r[1]]).sort((a, b) => a[0] - b[0]);
  const out: number[][] = [];
  for (const [s, e] of sorted) {
    const last = out[out.length - 1];
    if (last && s <= last[1]) last[1] = Math.max(last[1], e);
    else out.push([s, e]);
  }
  return out;
}

